-- Public read-only bucket for shared French pronunciation files.
-- Audio is generated by the Edge Function using the Supabase service role.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('french-audio', 'french-audio', true, 2097152, array['audio/mpeg','audio/ogg','audio/wav','audio/x-wav','audio/flac','audio/mp4','audio/webm','application/json'])
on conflict (id) do update
set public = true,
    file_size_limit = 2097152,
    allowed_mime_types = array['audio/mpeg'];

-- Anyone can play cached pronunciation files; only the Edge Function's
-- service-role credential can upload or replace objects.
drop policy if exists "Public can read French pronunciation audio" on storage.objects;
create policy "Public can read French pronunciation audio"
on storage.objects for select
to public
using (bucket_id = 'french-audio');
